205 |                     };
206 |                 }
207 | 
208 |                 if (!llmResponse) {
209 |                     const errorMsg = 'LLM returned null response';
210 |                     this.logger.error(errorMsg);
211 |                     spinner.fail(`Thinking-${i} failed`);
212 | 
213 |                    this.sessionManager.addMessage({
214 |                         role: 'assistant',
215 |                         type: 'text',
216 |                         content: errorMsg
217 |                     });
218 | 
219 |                     return {
220 |                         content: errorMsg,
